-- Calm Stories – core schema, indexes and Row Level Security.
--
-- Column names mirror src/lib/types.ts exactly so the application's
-- SupabaseDatabase adapter reads and writes rows without a mapping layer.
-- Primary keys are text (prefixed ids such as "ser_…") generated by the app.
--
-- Authorisation model
--  * The Next.js server uses the service-role key and enforces policy in
--    src/lib/auth/policy.ts (service role bypasses RLS).
--  * RLS below protects the same data for any direct client access with the
--    anon/authenticated keys (Realtime, mobile apps, analytics tools).
--  * users.auth_id links a Supabase Auth user to an application user.


-- ---------------------------------------------------------------------------
-- Identity, roles, entitlements
-- ---------------------------------------------------------------------------
create table public.users (
  id text primary key,
  auth_id uuid unique,                -- auth.users.id (Supabase Auth / Calm identity bridge)
  username text not null unique,
  display_name text not null,
  email text not null unique,
  avatar_hue int not null default 240,
  created_at timestamptz not null default now()
);

create table public.user_roles (
  id text primary key,
  user_id text not null references public.users(id) on delete cascade,
  role text not null check (role in ('admin', 'editor')),
  created_at timestamptz not null default now(),
  unique (user_id, role)
);

create table public.subscription_entitlements (
  id text primary key,
  user_id text not null references public.users(id) on delete cascade,
  plan text not null check (plan in ('free', 'premium')),
  status text not null check (status in ('active', 'expired', 'cancelled')),
  source text not null check (source in ('mock', 'calm')),
  expires_at timestamptz,
  created_at timestamptz not null default now()
);
create index on public.subscription_entitlements (user_id, status);

create table public.creator_profiles (
  id text primary key,
  user_id text not null unique references public.users(id) on delete cascade,
  username text not null unique,
  display_name text not null,
  bio text not null default '',
  is_official boolean not null default false,
  avatar jsonb not null,
  created_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Catalogue
-- ---------------------------------------------------------------------------
create table public.soundscapes (
  id text primary key,
  slug text not null unique,
  name text not null,
  description text not null default '',
  layers jsonb not null default '[]',
  licence text not null default '',
  sample_url text not null default '',
  created_at timestamptz not null default now()
);

create table public.series (
  id text primary key,
  slug text not null unique,
  creator_id text not null references public.users(id),
  title text not null,
  tagline text not null default '',
  description text not null default '',
  genre text not null,
  tags text[] not null default '{}',
  status text not null check (status in ('draft', 'in_review', 'published', 'archived', 'removed')),
  is_official boolean not null default false,
  artwork jsonb not null,
  soundscape_id text references public.soundscapes(id),
  content_rating text not null default 'all-ages',
  ai_disclosure text,
  trending_score numeric not null default 0,
  popularity numeric not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  published_at timestamptz
);
create index on public.series (creator_id);
create index on public.series (status, genre);

create table public.seasons (
  id text primary key,
  series_id text not null references public.series(id) on delete cascade,
  number int not null,
  title text not null,
  synopsis text not null default '',
  arc text not null default '',
  created_at timestamptz not null default now(),
  unique (series_id, number)
);

create table public.audio_assets (
  id text primary key,
  owner_id text references public.users(id),
  series_id text references public.series(id) on delete cascade,
  episode_id text,
  kind text not null check (kind in ('upload', 'sample', 'produced')),
  storage_key text not null,
  url text not null,
  mime_type text not null,
  duration_seconds numeric not null default 0,
  provider text not null,
  meta jsonb not null default '{}',
  created_at timestamptz not null default now()
);

create table public.episodes (
  id text primary key,
  series_id text not null references public.series(id) on delete cascade,
  season_id text not null references public.seasons(id) on delete cascade,
  number int not null,
  title text not null,
  summary text not null default '',
  duration_seconds int not null default 0,
  status text not null check (status in ('draft', 'in_review', 'changes_requested', 'approved', 'published', 'rejected')),
  release_at timestamptz,
  published_at timestamptz,
  audio_asset_id text references public.audio_assets(id) on delete set null,
  artwork_url text,
  is_preview boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index on public.episodes (series_id, season_id, number);
create index on public.episodes (status, release_at);
alter table public.audio_assets add constraint audio_assets_episode_fk foreign key (episode_id) references public.episodes(id) on delete cascade;
create index on public.audio_assets (episode_id, kind);

-- ---------------------------------------------------------------------------
-- Publishing, editorial, safety
-- ---------------------------------------------------------------------------
create table public.publishing_schedules (
  id text primary key,
  episode_id text not null references public.episodes(id) on delete cascade,
  series_id text not null references public.series(id) on delete cascade,
  release_at timestamptz not null,
  status text not null check (status in ('scheduled', 'released', 'cancelled')),
  created_by text not null references public.users(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index on public.publishing_schedules (status, release_at);

create table public.editorial_reviews (
  id text primary key,
  episode_id text not null references public.episodes(id) on delete cascade,
  series_id text not null references public.series(id) on delete cascade,
  submitted_by text not null references public.users(id),
  source text not null check (source in ('upload', 'agents')),
  status text not null check (status in ('pending', 'approved', 'rejected', 'changes_requested')),
  checks jsonb not null default '[]',
  requested_release_at timestamptz,
  reviewer_id text references public.users(id),
  notes text not null default '',
  created_at timestamptz not null default now(),
  decided_at timestamptz
);
create index on public.editorial_reviews (status, created_at);

create table public.content_reports (
  id text primary key,
  reporter_id text references public.users(id) on delete set null,
  target_type text not null check (target_type in ('series', 'episode', 'creator')),
  target_id text not null,
  reason text not null check (reason in ('copyright', 'inappropriate', 'not_sleep_friendly', 'impersonation', 'other')),
  details text not null default '',
  status text not null check (status in ('open', 'actioned', 'dismissed')),
  resolution text,
  created_at timestamptz not null default now(),
  resolved_at timestamptz
);
create index on public.content_reports (status, created_at);

-- ---------------------------------------------------------------------------
-- Listener data
-- ---------------------------------------------------------------------------
create table public.user_libraries (
  id text primary key,
  user_id text not null references public.users(id) on delete cascade,
  series_id text not null references public.series(id) on delete cascade,
  collection text not null default 'Saved',
  created_at timestamptz not null default now(),
  unique (user_id, series_id, collection)
);

create table public.series_follows (
  id text primary key,
  user_id text not null,  -- not an FK: seeded sample followers have no user row
  series_id text not null references public.series(id) on delete cascade,
  created_at timestamptz not null default now(),
  unique (user_id, series_id)
);
create index on public.series_follows (series_id);

create table public.creator_follows (
  id text primary key,
  user_id text not null references public.users(id) on delete cascade,
  creator_id text not null references public.users(id) on delete cascade,
  created_at timestamptz not null default now(),
  unique (user_id, creator_id),
  check (user_id <> creator_id)
);

create table public.listening_progress (
  id text primary key,                 -- `${user_id}:${episode_id}`
  user_id text not null references public.users(id) on delete cascade,
  episode_id text not null references public.episodes(id) on delete cascade,
  series_id text not null references public.series(id) on delete cascade,
  position_seconds int not null default 0,
  duration_seconds int not null default 0,
  completed boolean not null default false,
  updated_at timestamptz not null default now(),
  unique (user_id, episode_id)
);
create index on public.listening_progress (user_id, updated_at desc);

create table public.listening_events (
  id text primary key,
  user_id text references public.users(id) on delete cascade,
  anonymous_id text,
  episode_id text references public.episodes(id) on delete set null,
  series_id text references public.series(id) on delete set null,
  kind text not null check (kind in ('play', 'pause', 'complete', 'progress', 'seek', 'sleep_timer')),
  position_seconds int not null default 0,
  listened_seconds int not null default 0,
  is_sample boolean not null default false,
  created_at timestamptz not null default now()
);
create index on public.listening_events (series_id, created_at);
create index on public.listening_events (episode_id);

create table public.notifications (
  id text primary key,
  user_id text not null references public.users(id) on delete cascade,
  kind text not null check (kind in ('new_episode', 'review', 'production', 'system')),
  title text not null,
  body text not null default '',
  link text,
  read boolean not null default false,
  created_at timestamptz not null default now()
);
create index on public.notifications (user_id, read, created_at desc);

create table public.user_settings (
  id text primary key references public.users(id) on delete cascade,
  autoplay_next boolean not null default true,
  autoplay_limit int not null default 3,
  default_speed numeric not null default 1,
  default_sleep_timer_minutes int,
  new_episode_updates boolean not null default true,
  private_listening_history boolean not null default false,
  updated_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Agent production
-- ---------------------------------------------------------------------------
create table public.production_workflows (
  id text primary key,
  series_id text not null unique references public.series(id) on delete cascade,
  status text not null check (status in ('active', 'paused')),
  episodes_per_week int not null check (episodes_per_week between 1 and 7),
  release_days int[] not null,
  release_hour_utc int not null check (release_hour_utc between 0 and 23),
  target_minutes int not null check (target_minutes between 1 and 60),
  voice_id text,
  art_style text not null default '',
  story_notes text not null default '',
  budget_cents int not null default 500,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.production_jobs (
  id text primary key,
  series_id text not null references public.series(id) on delete cascade,
  episode_id text references public.episodes(id) on delete set null,
  workflow_id text references public.production_workflows(id) on delete set null,
  status text not null check (status in ('queued', 'running', 'paused', 'succeeded', 'failed', 'cancelled')),
  current_step text,
  steps jsonb not null default '[]',
  logs jsonb not null default '[]',
  payload jsonb not null default '{}',
  attempts int not null default 0,
  max_attempts int not null default 3,
  idempotency_key text unique,
  cost_cents numeric not null default 0,
  budget_cents numeric,
  error text,
  requested_by text references public.users(id),
  created_at timestamptz not null default now(),
  started_at timestamptz,
  finished_at timestamptz,
  updated_at timestamptz not null default now()
);
create index on public.production_jobs (status, created_at);
create index on public.production_jobs (series_id, created_at desc);

create table public.episode_scripts (
  id text primary key,
  episode_id text not null unique references public.episodes(id) on delete cascade,
  series_id text not null references public.series(id) on delete cascade,
  content text not null,
  word_count int not null default 0,
  provider text not null,
  model text not null,
  simulated boolean not null default false,
  notes text[] not null default '{}',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.artwork_assets (
  id text primary key,
  series_id text not null references public.series(id) on delete cascade,
  episode_id text references public.episodes(id) on delete cascade,
  kind text not null check (kind in ('cover', 'episode')),
  storage_key text not null,
  url text not null,
  mime_type text not null,
  provider text not null,
  model text not null,
  prompt text not null default '',
  created_at timestamptz not null default now()
);
create index on public.artwork_assets (series_id);

create table public.agent_settings (
  id text primary key check (id = 'global'),
  writer_model text not null,
  tts_model text not null,
  default_voice_id text not null,
  sfx_model text not null,
  image_model text not null,
  per_job_budget_cents int not null,
  max_concurrent_jobs int not null,
  updated_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Helper functions for RLS
-- ---------------------------------------------------------------------------
create or replace function public.app_user_id() returns text
language sql stable security definer set search_path = public as $$
  select id from public.users where auth_id = auth.uid()
$$;

create or replace function public.has_role(r text) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.user_roles where user_id = public.app_user_id() and role = r)
$$;

create or replace function public.is_editor() returns boolean
language sql stable as $$ select public.has_role('admin') or public.has_role('editor') $$;

create or replace function public.series_is_public(sid text) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.series where id = sid and status = 'published')
$$;

create or replace function public.episode_is_public(e public.episodes) returns boolean
language sql stable as $$
  select public.series_is_public(e.series_id)
     and (e.status = 'published' or (e.status = 'approved' and e.release_at <= now()))
$$;

-- ---------------------------------------------------------------------------
-- Row Level Security
-- ---------------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array[
    'users','user_roles','subscription_entitlements','creator_profiles','soundscapes','series','seasons',
    'audio_assets','episodes','publishing_schedules','editorial_reviews','content_reports','user_libraries',
    'series_follows','creator_follows','listening_progress','listening_events','notifications','user_settings',
    'production_workflows','production_jobs','episode_scripts','artwork_assets','agent_settings'
  ] loop
    execute format('alter table public.%I enable row level security', t);
  end loop;
end $$;

-- Own account
create policy users_self on public.users for select using (id = public.app_user_id() or public.is_editor());
create policy roles_self on public.user_roles for select using (user_id = public.app_user_id() or public.is_editor());
create policy ent_self on public.subscription_entitlements for select using (user_id = public.app_user_id() or public.is_editor());

-- Public reference data
create policy profiles_read on public.creator_profiles for select using (true);
create policy profiles_admin on public.creator_profiles for all using (public.has_role('admin')) with check (public.has_role('admin'));
create policy soundscapes_read on public.soundscapes for select using (true);

-- Catalogue: public once published; unreleased content is visible to Calm staff only.
-- All writes go through the server (service role) after editorial checks.
create policy series_read on public.series for select using (status = 'published' or public.is_editor());
create policy seasons_read on public.seasons for select using (public.series_is_public(series_id) or public.is_editor());
create policy episodes_read on public.episodes for select using (public.episode_is_public(episodes) or public.is_editor());

-- Audio: uploaded files are private (served through entitlement-checked routes); samples are public.
create policy audio_read on public.audio_assets for select using (kind = 'sample' or public.is_editor());

-- Editorial
create policy schedules_read on public.publishing_schedules for select using (public.is_editor());
create policy reviews_read on public.editorial_reviews for select using (public.is_editor());
create policy reviews_decide on public.editorial_reviews for update using (public.is_editor());
create policy reports_insert on public.content_reports for insert with check (reporter_id is null or reporter_id = public.app_user_id());
create policy reports_read on public.content_reports for select using (public.is_editor());

-- Agent production: Calm staff only (agents run server-side with the service role)
create policy workflows_staff on public.production_workflows for all using (public.is_editor()) with check (public.is_editor());
create policy jobs_staff on public.production_jobs for select using (public.is_editor());
create policy scripts_staff on public.episode_scripts for select using (public.is_editor());
create policy artwork_read on public.artwork_assets for select using (public.series_is_public(series_id) or public.is_editor());
create policy agent_settings_admin on public.agent_settings for all using (public.has_role('admin')) with check (public.has_role('admin'));

-- Listener-owned data
create policy library_own on public.user_libraries for all using (user_id = public.app_user_id()) with check (user_id = public.app_user_id());
create policy series_follows_own on public.series_follows for all using (user_id = public.app_user_id()) with check (user_id = public.app_user_id());
create policy creator_follows_own on public.creator_follows for all using (user_id = public.app_user_id()) with check (user_id = public.app_user_id());
create policy progress_own on public.listening_progress for all using (user_id = public.app_user_id()) with check (user_id = public.app_user_id());
create policy events_insert on public.listening_events for insert with check (user_id is null or user_id = public.app_user_id());
create policy events_read on public.listening_events for select using (user_id = public.app_user_id() or public.is_editor());
create policy notifications_own on public.notifications for all using (user_id = public.app_user_id()) with check (user_id = public.app_user_id());
create policy settings_own on public.user_settings for all using (id = public.app_user_id()) with check (id = public.app_user_id());


-- Storage bucket for episode audio and generated artwork.
insert into storage.buckets (id, name, public) values ('calm-stories', 'calm-stories', false) on conflict (id) do nothing;
